(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.02-t*0.22)*18 + Math.sin(x*0.016+t*0.3)*12;
  const sx = x + w1x, sy = y + w1y;
  const w2x = Math.sin(sx*0.025-t*0.4)*8 + Math.cos(sy*0.03+t*0.35)*6;
  const w2y = Math.cos(sy*0.028+t*0.45)*8 + Math.sin(sx*0.022-t*0.38)*6;
  const fx = sx + w2x, fy = sy + w2y;
  const src = [
    [160+Math.sin(t*0.55)*110, 75+Math.cos(t*0.4)*55, 0.085, 2.1, 1.0],
    [320+Math.cos(t*0.48)*110, 165+Math.sin(t*0.65)*55, 0.095, 1.8, 0.9],
    [240+Math.sin(t*0.32+2)*150, 115+Math.cos(t*0.5+1)*95, 0.065, 2.4, 1.1],
    [110+Math.cos(t*0.75+1)*85, 185+Math.sin(t*0.58+3)*65, 0.11, 1.6, 0.85],
    [370+Math.sin(t*0.42+4)*95, 55+Math.cos(t*0.85+2)*75, 0.075, 2.7, 1.05],
    [240+Math.cos(t*0.38+5)*130, 205+Math.sin(t*0.52)*85, 0.088, 2.0, 0.95],
    [80+Math.sin(t*0.6+3)*70, 50+Math.cos(t*0.7+1)*60, 0.1, 1.9, 0.8],
    [400+Math.cos(t*0.45+2)*80, 190+Math.sin(t*0.55+4)*70, 0.07, 2.5, 1.15]
  ];
  let aS=0, iS=0, a2=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((fx-sX)**2 + (fy-sY)**2);
    const wave = Math.sin(d*f - t*sp);
    aS += wave * w;
    iS += Math.sin(d*f*0.65 + t*sp*0.55 + 1.5) * w;
    a2 += Math.sin(d*f*1.3 - t*sp*0.8 + 2.0) * w * 0.5;
  }
  const act = aS/8, inh = iS/8, act2 = a2/8;
  const bg = (Math.sin(fx*0.038+fy*0.024+t*0.75)+Math.sin(fx*0.028-fy*0.038+t*1.05))/2
    + Math.sin((fx+fy)*0.11+t*2.3)*0.18 + Math.sin((fx-fy)*0.095-t*1.8)*0.18;
  const dist = Math.sqrt((fx-cx)**2+(fy-cy)**2), ang = Math.atan2(fy-cy, fx-cx);
  const spiral = (Math.sin(dist*0.048-ang*3.5-t*1.4)+Math.sin(dist*0.038+ang*4.5-t*1.1))*0.35;
  const radial = Math.sin(dist*0.06-t*0.8)*0.15;
  const reaction = act - inh*0.65 + bg*0.25 + spiral + radial + act2*0.2;
  const rd2 = reaction*reaction*0.15 - 0.1;
  const cell = Math.tanh((Math.sin(fx*0.14)*Math.sin(fy*0.14)+Math.sin((fx+fy)*0.095+t)*0.45)*1.4)*0.25;
  const micro = Math.sin(fx*0.45+fy*0.35+t*3)*Math.sin(fx*0.3-fy*0.4-t*2.5)*0.08;
  const raw = Math.tanh((reaction + rd2 + cell + micro)*2.0);
  const edge = 1.0 - Math.abs(raw);
  const edgeGlow = Math.exp(-edge*8)*0.3;
  const v = raw*0.5+0.5+edgeGlow;
  const pal = [
    [6,12,52],[12,45,88],[18,85,115],[25,135,125],[45,170,120],
    [140,190,80],[210,185,60],[225,145,55],[215,100,65],
    [185,60,75],[120,35,65],[65,22,55],[30,14,50],[6,12,52]
  ];
  const idx = Math.max(0,Math.min(v*(pal.length-1), pal.length-1.001));
  const i = idx|0, f = idx-i;
  const lum = 0.82+Math.sin(raw*Math.PI)*0.18;
  const ef = Math.abs(raw)>0.65?1.12:1.0;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*ef+edgeGlow*40)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*ef+edgeGlow*60)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*ef+edgeGlow*80)|0
  ];
}
